<script setup>
import {reactive,ref,watch} from 'vue'
import ModalDialog from '../../../shared/ui/ModalDialog.vue'
import {useEvidence} from '../../../entities/evidence/model/state.js'
import {useWorkspace} from '../../../entities/monitor/model/workspace.js'
const props=defineProps({index:Number}),emit=defineEmits(['close'])
const {rules,load}=useEvidence(),{api,notify}=useWorkspace(),form=reactive({reason:'',steps:[],notes:''}),busy=ref(false),error=ref(''),deleting=ref(false)
watch(()=>props.index,index=>{if(index===null)return;const r=rules.value[index];form.reason=r.reason;form.steps=[...r.steps];if(!form.steps.length)form.steps=[''];form.notes=r.notes;error.value='';deleting.value=false},{immediate:true})
function close(){if(!busy.value)emit('close')}
async function save(remove=false){
 if(busy.value)return;busy.value=true;error.value=''
 try{const rule={reason:form.reason.trim(),steps:form.steps.map(s=>s.trim()),notes:form.notes.trim()};if(!remove&&rules.value.some((r,i)=>i!==props.index&&r.reason===rule.reason))throw new Error('已有同名规则，请修改原规则');const values=rules.value.map((r,i)=>i===props.index?rule:r).filter((r,i)=>!remove||i!==props.index);await api('/api/rules',{rules:values},{evidence:true});window.dispatchEvent(new Event('workbench-backups-changed'));deleting.value=false;emit('close');notify(remove?'规则已删除':'规则已保存');await load().catch(()=>{})}catch(e){error.value=e.message}finally{busy.value=false}
}
</script>
<template><ModalDialog id="ev-rules-editor" :open="index!==null" label="编辑规则" @close="close"><form id="ev-rules-form" @submit.prevent="save(false)"><div class="modal-header"><h2>编辑规则</h2><button type="button" class="icon-button" aria-label="关闭规则编辑" @click="close">×</button></div><div class="modal-body"><label class="block-label">违规行为 <em>*</em><input v-model="form.reason" required maxlength="500" :disabled="busy"></label><h3 class="small-heading">分次处理</h3><div id="ev-rule-steps"><label v-for="(_,i) in form.steps" :key="i" class="block-label rule-step">第 {{i+1}} 次<input v-model="form.steps[i]" :disabled="busy" maxlength="1000" :aria-label="'第 '+(i+1)+' 次处理'" placeholder="留空表示未设定处理办法"></label><button v-if="form.steps.length>1" type="button" class="button subtle remove-step" :disabled="busy" @click="form.steps.pop()">移除最后一档</button></div><button class="button subtle" type="button" :disabled="busy||form.steps.length>=10" @click="form.steps.push('')">添加下一次处理</button><label class="block-label rule-notes">补充说明 <span class="optional">选填</span><textarea v-model="form.notes" :disabled="busy" rows="3" maxlength="10000" placeholder="如严重情形、处理范围"></textarea></label><p role="alert">{{error}}</p></div><div class="modal-footer"><button v-if="rules.length>1" type="button" class="delete-link" :disabled="busy" @click="deleting=true;error=''">删除规则</button><button type="button" class="button" :disabled="busy" @click="close">取消</button><button type="submit" class="button primary" :disabled="busy">保存规则</button></div></form></ModalDialog><ModalDialog id="ev-rule-delete-dialog" :open="deleting" label="确认删除规则" @close="!busy&&(deleting=false)"><div class="confirm-content"><h2>删除这条规则？</h2><p>{{form.reason}}</p><div><button class="button" :disabled="busy" @click="deleting=false">取消</button><button class="button danger" :disabled="busy" @click="save(true)">确认删除规则</button></div><p role="alert">{{error}}</p></div></ModalDialog></template>
